const state={projects:[],project:null,pollers:new Map(),tasks:null,sceneConfigOpen:new Map(),expandedSegments:new Map(),user:null,taskTimer:null,pendingSegmentImages:new Map()};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
async function api(path,options={}){const r=await fetch(path,options);if(r.status===401&&path!=='/api/auth/login'){showLogin();throw new Error('登录已失效，请重新登录')}if(!r.ok){let e;try{e=(await r.json()).detail}catch{e=await r.text()}throw new Error(typeof e==='string'?e:JSON.stringify(e))}return r.status===204?null:r.json()}
function showLogin(){state.user=null;state.project=null;$('#loginScreen').classList.remove('hidden');$('.shell').classList.add('session-hidden');$('.topbar').classList.add('session-hidden');$('.session-actions').classList.add('session-hidden');if(state.taskTimer)clearInterval(state.taskTimer)}
function startSession(user){state.user=user;$('#loginScreen').classList.add('hidden');$('.shell').classList.remove('session-hidden');$('.topbar').classList.remove('session-hidden');$('.session-actions').classList.remove('session-hidden');$('#currentUsername').textContent=user.username;$('#llmConfigBtn').classList.toggle('hidden',!user.is_admin);$$('.admin-only').forEach(el=>el.classList.toggle('hidden',!user.is_admin));refreshTasks();if(state.taskTimer)clearInterval(state.taskTimer);state.taskTimer=setInterval(refreshTasks,4000);loadProjects().catch(e=>toast(e.message,true))}
async function login(e){e.preventDefault();const button=$('#loginBtn');button.disabled=true;$('#loginError').textContent='';try{const user=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#loginUsername').value.trim(),password:$('#loginPassword').value})});$('#loginPassword').value='';startSession(user)}catch(e){$('#loginError').textContent=e.message}finally{button.disabled=false}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}finally{showLogin()}}
async function loadUsers(){const users=await api('/api/admin/users');$('#userList').innerHTML=users.map(user=>`<article class="user-row" data-user-id="${user.id}"><div><b>${esc(user.username)}</b><small>${user.is_admin?'管理员':`${user.project_count} 个项目`} · ${user.is_active?'已启用':'已停用'}</small></div><div>${user.is_admin?'':`<button data-user-status="${user.id}">${user.is_active?'停用':'启用'}</button>`}<button data-user-password="${user.id}">修改密码</button></div></article>`).join('');$$('[data-user-status]').forEach(button=>button.onclick=()=>setUserStatus(+button.dataset.userStatus));$$('[data-user-password]').forEach(button=>button.onclick=()=>resetUserPassword(+button.dataset.userPassword))}
async function openUserAdmin(){await loadUsers();$('#newUsername').value='';$('#newUserPassword').value='';$('#userAdminDialog').showModal()}
async function createUser(e){e.preventDefault();try{await api('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#newUsername').value.trim(),password:$('#newUserPassword').value})});$('#newUsername').value='';$('#newUserPassword').value='';await loadUsers();toast('用户已创建')}catch(e){toast(e.message,true)}}
async function setUserStatus(id){const row=$(`.user-row[data-user-id="${id}"]`),enable=row.querySelector('small').textContent.includes('已停用');if(!confirm(enable?'确认启用这个用户？':'确认停用这个用户？该用户当前会话将立即失效。'))return;try{await api(`/api/admin/users/${id}/status`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({is_active:enable})});await loadUsers();toast(enable?'用户已启用':'用户已停用')}catch(e){toast(e.message,true)}}
async function resetUserPassword(id){const password=prompt('请输入新密码（至少6个字符）');if(password===null)return;if(password.length<6)return toast('密码至少6个字符',true);try{await api(`/api/admin/users/${id}/password`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});await loadUsers();toast('密码已修改，原有会话已失效')}catch(e){toast(e.message,true)}}
function toast(msg,error=false){const el=$('#toast'),dialog=[...$$('dialog[open]')].at(-1);(dialog||document.body).appendChild(el);el.classList.toggle('in-dialog',!!dialog);el.textContent=msg;el.className='toast show'+(error?' error':'')+(dialog?' in-dialog':'');clearTimeout(el.t);el.t=setTimeout(()=>el.className='toast',3200)}
function esc(s=''){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
async function refreshTasks(){try{const t=await api('/api/tasks/status');state.tasks=t;const running=t.total?.running??(t.web.running+t.comfyui.running),queued=t.total?.queued??(t.web.queued+t.comfyui.pending),dot=$('#healthDot');dot.classList.toggle('online',t.state==='idle');dot.classList.toggle('busy',t.state==='busy');$('#healthText').textContent=t.state==='offline'?'GPU 离线':t.state==='busy'?'GPU 繁忙':'GPU 空闲';$('#queueText').textContent=t.state==='offline'?'请检查 ComfyUI':t.busy?`${running} 个生成中 · ${queued} 个等待`:'可以提交新任务';renderTaskCenter(t);return t}catch{$('#healthText').textContent='GPU 状态异常';$('#queueText').textContent='点击重试';return null}}
function taskTime(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function formatDuration(total){if(total==null)return '计算中';total=Math.max(0,Math.round(total));const h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;if(h)return `${h}小时 ${m}分`;if(m)return `${m}分 ${s}秒`;return `${s}秒`}
function taskTiming(j){if(j.status==='queued')return `已等待 ${formatDuration(j.waiting_seconds)}`;const prefix=j.elapsed_basis==='observed'?'已观测执行':'已执行',elapsed=`${prefix} ${formatDuration(j.elapsed_seconds)}`;if(j.status!=='running')return elapsed;if(j.estimated_finish_at)return `${elapsed} · 剩余约 ${formatDuration(j.remaining_seconds)} · 预计 ${new Date(j.estimated_finish_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})} 完成`;return `${elapsed} · 预计时间计算中`}
function renderTaskRows(items,active){if(!items.length)return '<div class="global-task-empty">'+(active?'当前没有运行或等待的任务':'暂无任务记录')+'</div>';return items.map(j=>{const hasProgress=j.progress_available&&j.progress!=null,pct=hasProgress?Math.round(j.progress*100):null,external=j.source==='comfyui',status=j.status==='running'?'正在生成':j.status==='queued'?`排队第 ${j.queue_position} 位`:j.status==='complete'?'已完成':j.status==='cancelled'?'已取消':'失败',identity=external?'ComfyUI 外部任务':`${esc(j.project_name)} · 片段 ${j.segment_position+1}`,detail=external?`${esc(j.task_mode||'视频')} · ${esc(j.duration_label||'')}`:`${esc(j.segment_title)} · ${j.duration} 秒`;return `<div class="global-task"><div><b>${identity}</b><small>${esc(j.segment_title)} · ${detail} · ${taskTime(j.created_at)}</small>${external?`<small>Prompt ID: ${esc((j.prompt_id||'').slice(0,13))}…</small>`:''}<small class="task-timing">${esc(taskTiming(j))}</small></div><div><small>${esc(j.phase||'')}</small>${active?`<div class="global-progress ${!hasProgress&&j.status==='running'?'indeterminate':''}"><i style="width:${hasProgress?pct:35}%"></i></div>`:`<small>${j.error?esc(j.error):taskTime(j.finished_at)}</small>`}</div><div class="global-task-state"><strong class="${j.status==='complete'?'ok':j.status==='failed'?'fail':''}">${status}</strong>${active?`<small>${hasProgress?pct+'%':j.status==='running'?'百分比待启用':'等待中'}</small>`:''}</div></div>`}).join('')}
function renderTaskCenter(t){if(!t)return;$('#serverState').textContent=t.state==='idle'?'空闲':t.state==='busy'?'繁忙':'离线';$('#runningCount').textContent=t.total?.running??(t.web.running+t.comfyui.running);$('#queuedCount').textContent=t.total?.queued??(t.web.queued+t.comfyui.pending);$('#comfyQueueCount').textContent=t.comfyui.running+t.comfyui.pending;$('#activeTaskList').innerHTML=renderTaskRows(t.active,true);$('#recentTaskList').innerHTML=renderTaskRows(t.recent,false)}
async function loadProjects(selectId){state.projects=await api('/api/projects');renderProjects();if(selectId)await selectProject(selectId);else if(state.project){const found=state.projects.find(p=>p.id===state.project.id);if(found)await selectProject(found.id);else showEmpty()}else if(state.projects.length)await selectProject(state.projects[0].id);else showEmpty()}
function renderProjects(){$('#projectList').innerHTML=state.projects.map(p=>`<div class="project-item ${state.project?.id===p.id?'active':''}" data-id="${p.id}"><b>${esc(p.name)}</b><small>${p.segment_count} 个故事片段</small></div>`).join('');$$('.project-item').forEach(el=>el.onclick=()=>selectProject(+el.dataset.id))}
function showEmpty(){$('#emptyState').classList.remove('hidden');$('#projectView').classList.add('hidden');state.project=null;renderProjects()}
async function selectProject(id){state.project=await api(`/api/projects/${id}`);$('#emptyState').classList.add('hidden');$('#projectView').classList.remove('hidden');fillProject();renderProjects();renderCombinedVideos();renderSegments();enhanceVideoCards();enhanceMergeSelectors();enhanceRunningCancelButtons();syncDeleteButtons();renderEpisodeShelf();requestAnimationFrame(drawRelations)}
function fillProject(){const p=state.project;$('#projectName').value=p.name;$('#characterPrompt').value=p.character_prompt;$('#environmentPrompt').value=p.environment_prompt;$('#continuityNegativePrompt').value=p.continuity_negative_prompt||'';$('#visualPrompt').value=p.visual_prompt;$('#audioPrompt').value=p.audio_prompt;$('#canvas').value=`${p.width}x${p.height}`;$('#steps').value=p.steps;$('#seed').value=p.seed;for(const slot of [1,2]){const box=$(`.photo-slot[data-slot="${slot}"]`),ref=p.references.find(r=>r.slot===slot);box.classList.toggle('has-image',!!ref);box.querySelector('img').src=ref?`/api/references/${p.id}/${slot}?t=${Date.now()}`:''}const configured=!!p.references.length&&[p.character_prompt,p.environment_prompt,p.continuity_negative_prompt,p.visual_prompt,p.audio_prompt].every(value=>value?.trim()),details=$('#sceneConfig');$('#sceneConfigStatus').textContent=configured?'人物与世界设定已配置':'配置未完成，请展开补充';details.open=state.sceneConfigOpen.has(p.id)?state.sceneConfigOpen.get(p.id):!configured}
async function saveProject(){if(!state.project)return;const [width,height]=$('#canvas').value.split('x').map(Number);const body={name:$('#projectName').value.trim(),character_prompt:$('#characterPrompt').value,environment_prompt:$('#environmentPrompt').value,continuity_negative_prompt:$('#continuityNegativePrompt').value,visual_prompt:$('#visualPrompt').value,audio_prompt:$('#audioPrompt').value,width,height,steps:+$('#steps').value,seed:+$('#seed').value};state.project=await api(`/api/projects/${state.project.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('项目设定已保存');await loadProjects(state.project.id)}
async function downloadExport(button,path,label,fallback){button.disabled=true;const original=button.textContent;button.textContent='正在导出…';try{const response=await fetch(path);if(!response.ok)throw new Error((await response.json()).detail||'导出失败');const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=match?.[1]||fallback;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast(label)}catch(e){toast(e.message,true)}finally{button.disabled=false;button.textContent=original}}
function exportProject(){if(state.project)downloadExport($('#exportProjectBtn'),`/api/projects/${state.project.id}/export`,'完整项目配置已导出',`sceneflow_project_${state.project.id}_full.json`)}
function exportStoryboard(){if(state.project)downloadExport($('#exportStoryboardBtn'),`/api/projects/${state.project.id}/export-storyboard`,'分镜故事已导出',`sceneflow_project_${state.project.id}_storyboard.txt`)}
function renderSegments(){const list=$('#segmentList'),segments=state.project.segments;if(!segments.length){list.innerHTML='<div class="segment-empty"><b>还没有故事片段</b><p>添加第一个2至20秒镜头。</p></div>';return}const byId=new Map(segments.map(s=>[s.id,s]));list.innerHTML='<svg class="relation-svg" aria-hidden="true"></svg>'+segments.map((s,i)=>{const j=s.latest_job,active=j&&['queued','running'].includes(j.status),pct=Math.round((j?.progress||0)*100),source=byId.get(s.continuity_source_id),hasChildren=s.children?.length;return `<article class="segment-card ${source?'relation-target':''} ${hasChildren?'relation-source':''}" data-id="${s.id}"><div class="segment-main"><div class="segment-no">${String(i+1).padStart(2,'0')}</div><div class="segment-copy"><h3>${esc(s.title)}</h3><div class="segment-meta"><span class="chip">片段 ${i+1}</span><span class="chip chain">串联 ${s.chain_order||i+1}</span><span class="chip">${s.duration} 秒 · ${s.frame_count} 帧</span><span class="chip ${s.continuity_mode}">${s.continuity_mode==='continue'&&source?`接续片段 ${source.position+1}`:'新镜头硬切'}</span>${source?`<span class="chip relation">来源：${esc(source.title)}</span>`:''}${hasChildren?`<span class="chip relation">后续：${s.children.map(id=>'片段 '+(byId.get(id)?.position+1)).join('、')}</span>`:''}${s.refine_enabled?`<span class="chip refine">二次精修 · ${s.refine_denoise} / ${s.refine_steps||'自动'}步</span>`:''}<span class="chip">${s.status==='complete'?'已有成片':s.status==='queued'?'排队中':s.status==='running'?'生成中':s.status==='failed'?'生成失败':'草稿'}</span></div><p>${esc(s.prompt)}</p></div><div class="segment-actions"><div class="chain-controls"><button data-chain="up" title="串联编号上移">↑</button><button data-chain="down" title="串联编号下移">↓</button></div><button data-a="edit">编辑</button>${i===segments.length-1?'<button data-a="delete">删除</button>':''}<button class="generate" data-a="generate" ${active?'disabled':''}>${active?'生成中':'生成片段'}</button></div></div>${j?`<div class="job-progress ${j.status==='complete'?'hidden':''}"><div class="progress-head"><span>${esc(j.phase||'')}</span><b>${pct}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>${j.error?`<div class="job-error">${esc(j.error)}</div>`:''}</div>`:''}${s.videos.length?`<div class="video-list">${s.videos.map(v=>`<div class="video-item"><video controls preload="metadata" src="/api/videos/${v.id}/stream"></video><div class="video-foot"><span>${formatSize(v.size_bytes)}</span><div><a href="/api/videos/${v.id}/stream?download=true">下载</a><button data-video-delete="${v.id}">删除</button></div></div></div>`).join('')}</div>`:''}</article>`}).join('');$$('.segment-card').forEach(card=>{const s=segments.find(x=>x.id===+card.dataset.id);card.querySelector('[data-a="edit"]').onclick=()=>openSegment(s);card.querySelector('[data-a="generate"]').onclick=()=>generate(s);card.querySelector('[data-a="delete"]')?.addEventListener('click',()=>requestDeleteSegment(s));card.querySelector('[data-chain="up"]').onclick=()=>moveChain(s.id,-1);card.querySelector('[data-chain="down"]').onclick=()=>moveChain(s.id,1);card.querySelectorAll('[data-video-delete]').forEach(b=>b.onclick=()=>deleteVideo(+b.dataset.videoDelete))});segments.forEach(s=>{if(s.latest_job&&['queued','running'].includes(s.latest_job.status))pollJob(s.latest_job.id)})}
function drawRelations(){const list=$('#segmentList'),svg=list?.querySelector('.relation-svg');if(!svg||!state.project)return;const root=list.getBoundingClientRect(),byId=new Map(state.project.segments.map(s=>[s.id,s]));svg.setAttribute('viewBox',`0 0 42 ${Math.max(1,list.scrollHeight)}`);svg.innerHTML=state.project.segments.filter(s=>s.continuity_source_id&&byId.has(s.continuity_source_id)).map(s=>{const sourceCard=list.querySelector(`[data-id="${s.continuity_source_id}"]`),targetCard=list.querySelector(`[data-id="${s.id}"]`);if(!sourceCard?.offsetParent||!targetCard?.offsetParent)return '';const source=sourceCard.getBoundingClientRect(),target=targetCard.getBoundingClientRect(),y1=source.bottom-root.top-18,y2=target.top-root.top+18,x1=29,x2=29,bend=Math.min(16,Math.abs(y2-y1)/3);return `<path d="M ${x1} ${y1} C 7 ${y1+bend}, 7 ${y2-bend}, ${x2} ${y2}" fill="none" stroke="#3f8067" stroke-width="3" stroke-linecap="round"/>`}).join('')}
async function moveChain(id,delta){const ordered=[...state.project.segments].sort((a,b)=>(a.chain_order||a.position+1)-(b.chain_order||b.position+1)),index=ordered.findIndex(s=>s.id===id),next=index+delta;if(index<0||next<0||next>=ordered.length)return;[ordered[index],ordered[next]]=[ordered[next],ordered[index]];try{await api(`/api/projects/${state.project.id}/chain-order`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({segment_ids:ordered.map(s=>s.id)})});await selectProject(state.project.id)}catch(e){toast(e.message,true)}}
function formatSize(n){return n>1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.round(n/1024)} KB`}
function formatVideoTime(seconds){seconds=Number(seconds||0);const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return m?`${m}:${String(s).padStart(2,'0')}`:`${seconds.toFixed(1)}秒`}
function enhanceVideoCards(){for(const segment of state.project?.segments||[]){const card=$(`.segment-card[data-id="${segment.id}"]`);if(!card)continue;if(segment.latest_job?.status==='queued'){const generateButton=card.querySelector('[data-a="generate"]');generateButton.insertAdjacentHTML('afterend','<button class="cancel-job" data-a="cancel-job">取消排队</button>');card.querySelector('[data-a="cancel-job"]').onclick=()=>cancelJob(segment.latest_job.id)}const items=[...card.querySelectorAll('.video-item')];segment.videos.forEach((video,index)=>{const item=items[index];if(!item)return;item.dataset.videoId=video.id;const player=item.querySelector('video'),foot=item.querySelector('.video-foot'),frames=video.keyframes||[],version=encodeURIComponent(video.cache_version);player.src=`/api/videos/${video.id}/stream?v=${version}`;item.classList.toggle('latest',video.is_latest);item.insertAdjacentHTML('afterbegin',`<div class="video-tags">${video.is_latest?'<span class="video-tag latest">最新生成</span>':''}<span class="video-tag ${video.refined?'refined':''}">${video.refined?'已精修':'未精修'}</span><span class="video-tag">生成：${taskTime(video.created_at)}</span><span class="video-tag">时长：${formatVideoTime(video.duration_seconds)}</span>${video.width&&video.height?`<span class="video-tag">${video.width}×${video.height}</span>`:''}</div>`);if(frames.length)player.insertAdjacentHTML('afterend',`<div class="keyframe-strip">${frames.map((frame,frameIndex)=>`<button class="keyframe-shot" data-frame-time="${frame.time}" title="跳转到 ${formatVideoTime(frame.time)}"><img loading="lazy" src="/api/videos/${video.id}/keyframes/${frameIndex}?v=${version}"><span>${formatVideoTime(frame.time)}</span></button>`).join('')}</div>`);foot.querySelector('span').textContent=`${formatSize(video.size_bytes)} · ${frames.length}张关键帧`;foot.querySelector('a').href=`/api/videos/${video.id}/stream?download=true&v=${version}`;item.querySelectorAll('.keyframe-shot').forEach(button=>button.onclick=()=>{player.currentTime=+button.dataset.frameTime;player.play()});item.querySelector('[data-video-delete]').onclick=()=>requestDeleteVideo(video.id)})}}
function enhanceMergeSelectors(){for(const segment of state.project?.segments||[]){for(const video of segment.videos){const item=$(`.video-item[data-video-id="${video.id}"]`),foot=item?.querySelector('.video-foot');if(!item||!foot)continue;item.classList.toggle('merge-selected',video.selected_for_merge);const selector=document.createElement('label');selector.className='merge-selector';selector.innerHTML=`<input type="radio" name="merge-video-${segment.id}" value="${video.id}" ${video.selected_for_merge?'checked':''}><span>${video.selected_for_merge?'已选用于合并':'用于合并'}</span>`;foot.insertBefore(selector,foot.lastElementChild);selector.querySelector('input').onchange=()=>selectMergeVideo(segment,video)}}}
async function selectMergeVideo(segment,video){const inputs=$$(`input[name="merge-video-${segment.id}"]`);inputs.forEach(input=>input.disabled=true);try{await api(`/api/segments/${segment.id}/selected-video`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({video_id:video.id})});segment.selected_video_id=video.id;for(const item of segment.videos)item.selected_for_merge=item.id===video.id;for(const item of segment.videos){const card=$(`.video-item[data-video-id="${item.id}"]`),input=card?.querySelector('.merge-selector input'),label=card?.querySelector('.merge-selector span');card?.classList.toggle('merge-selected',item.selected_for_merge);if(input)input.checked=item.selected_for_merge;if(label)label.textContent=item.selected_for_merge?'已选用于合并':'用于合并'}toast(`已选择这个版本用于片段${segment.display_order}合并`)}catch(e){const selected=segment.videos.find(item=>item.selected_for_merge);for(const input of inputs)input.checked=+input.value===selected?.id;toast(e.message,true)}finally{inputs.forEach(input=>input.disabled=false)}}
function expandedSegmentIds(){if(!state.expandedSegments.has(state.project.id))state.expandedSegments.set(state.project.id,new Set());return state.expandedSegments.get(state.project.id)}
function renderEpisodeShelf(){const list=$('#segmentList'),expanded=expandedSegmentIds(),episodes=state.project.segments.filter(s=>s.status==='complete'&&s.videos.length&&!expanded.has(s.id));list.querySelector('.episode-shelf')?.remove();for(const segment of state.project.segments){const card=list.querySelector(`.segment-card[data-id="${segment.id}"]`);card?.classList.toggle('episode-collapsed',episodes.includes(segment));if(card&&expanded.has(segment.id)&&segment.status==='complete'&&segment.videos.length&&!card.querySelector('[data-a="collapse"]')){const button=document.createElement('button');button.dataset.a='collapse';button.textContent='收起';button.onclick=()=>{expanded.delete(segment.id);renderEpisodeShelf();requestAnimationFrame(drawRelations)};card.querySelector('.segment-actions').insertBefore(button,card.querySelector('[data-a="generate"]'))}}if(!episodes.length)return;const shelf=document.createElement('section');shelf.className='episode-shelf';shelf.innerHTML=`<div class="episode-shelf-head"><div><span class="eyebrow">GENERATED EPISODES</span><h3>已生成剧集</h3></div><small>${episodes.length} 个片段 · 按当前故事顺序</small></div><div class="episode-grid">${episodes.map(s=>{const video=s.videos[0],frame=video.keyframes?.[0],version=encodeURIComponent(video.cache_version),cover=frame?`<img loading="lazy" src="/api/videos/${video.id}/keyframes/0?v=${version}" alt="${esc(s.title)}">`:'<span class="episode-no-cover">暂无封面</span>';return `<article class="episode-card" data-episode-id="${s.id}"><div class="episode-cover">${cover}<span class="episode-index">${String(s.display_order||s.position+1).padStart(2,'0')}</span><button class="episode-edit" title="展开并编辑" aria-label="展开并编辑 ${esc(s.title)}">✎</button><span class="episode-duration">${s.duration}秒</span></div><div class="episode-title"><b>${esc(s.title)}</b><small>片段 ${s.display_order||s.position+1}</small></div></article>`}).join('')}</div>`;list.querySelector('.relation-svg').insertAdjacentElement('afterend',shelf);shelf.querySelectorAll('.episode-card').forEach(card=>{const segment=state.project.segments.find(s=>s.id===+card.dataset.episodeId);card.querySelector('.episode-edit').onclick=e=>{e.stopPropagation();expanded.add(segment.id);renderEpisodeShelf();requestAnimationFrame(()=>{drawRelations();list.querySelector(`.segment-card[data-id="${segment.id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'});openSegment(segment)})};card.onclick=()=>{expanded.add(segment.id);renderEpisodeShelf();requestAnimationFrame(()=>{drawRelations();list.querySelector(`.segment-card[data-id="${segment.id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})})}})}
renderEpisodeShelf=function(){const list=$('#segmentList'),segments=state.project?.segments||[],expanded=expandedSegmentIds();list.querySelector('.episode-shelf')?.remove();if(!segments.length)return;for(const segment of segments){const card=list.querySelector(`.segment-card[data-id="${segment.id}"]`),hasVideo=segment.videos.length>0,isExpanded=expanded.has(segment.id);card?.classList.toggle('episode-collapsed',hasVideo&&!isExpanded);card?.querySelector('[data-a="collapse"]')?.remove();if(hasVideo&&isExpanded&&card){const button=document.createElement('button');button.dataset.a='collapse';button.textContent='收起';button.onclick=()=>{expanded.delete(segment.id);renderEpisodeShelf();requestAnimationFrame(drawRelations)};card.querySelector('.segment-actions').insertBefore(button,card.querySelector('[data-a="generate"]'))}}const shelf=document.createElement('section');shelf.className='episode-shelf';shelf.innerHTML=`<div class="episode-shelf-head"><div><span class="eyebrow">STORY SEGMENTS</span><h3>已生成剧集</h3></div><small>${segments.length} 个片段 · 按当前故事顺序</small></div><div class="episode-grid">${segments.map(segment=>{const video=segment.videos[0],frame=video?.keyframes?.[0],version=video?encodeURIComponent(video.cache_version):'',cover=frame?`<img loading="lazy" src="/api/videos/${video.id}/keyframes/0?v=${version}" alt="${esc(segment.title)}">`:'<span class="episode-no-cover"><svg viewBox="0 0 48 48" aria-hidden="true"><rect x="8" y="11" width="32" height="26" rx="4"/><circle cx="18" cy="20" r="3"/><path d="m12 33 9-8 6 5 5-4 5 7"/><path d="M10 39 38 9"/></svg><b>无图</b></span>';return `<article class="episode-card ${expanded.has(segment.id)?'expanded':''}" data-episode-id="${segment.id}"><div class="episode-cover">${cover}<span class="episode-index">${String(segment.display_order||segment.position+1).padStart(2,'0')}</span><button class="episode-edit" title="展开并编辑" aria-label="展开并编辑 ${esc(segment.title)}">✎</button><span class="episode-duration">${segment.duration}秒</span></div><div class="episode-title"><b>${esc(segment.title)}</b><small>${video?`${segment.videos.length} 个视频`:'尚无视频'}</small></div></article>`}).join('')}</div>`;list.querySelector('.relation-svg')?.insertAdjacentElement('afterend',shelf);shelf.querySelectorAll('.episode-card').forEach(item=>{const id=+item.dataset.episodeId,segment=segments.find(value=>value.id===id);item.querySelector('.episode-edit').onclick=event=>{event.stopPropagation();if(segment.videos.length)expanded.add(id);renderEpisodeShelf();requestAnimationFrame(()=>{drawRelations();openSegment(segment)})};item.onclick=()=>{if(segment.videos.length)expanded.add(id);renderEpisodeShelf();requestAnimationFrame(()=>{drawRelations();list.querySelector(`.segment-card[data-id="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})})}})};
function syncDeleteButtons(){for(const segment of state.project?.segments||[]){const card=$(`.segment-card[data-id="${segment.id}"]`),actions=card?.querySelector('.segment-actions'),existing=actions?.querySelector('[data-a="delete"]');if(!actions)continue;if(!segment.can_delete){existing?.remove();continue}if(!existing){const button=document.createElement('button');button.dataset.a='delete';button.textContent='删除';button.onclick=()=>requestDeleteSegment(segment);actions.insertBefore(button,actions.querySelector('[data-a="generate"]'))}}}
function toggleRefineOptions(){const enabled=$('#refineEnabled').checked;$('#refineOptions').classList.toggle('hidden',!enabled)}
function toggleSourceOptions(){const enabled=$('input[name="continuity"]:checked').value==='continue';$('#sourceSegmentRow').classList.toggle('hidden',!enabled)}
function openSegment(s=null){const isFirst=!s&&state.project.segments.length===0;$('#editingSegmentId').value=s?.id||'';$('#segmentTitle').value=s?.title||'';$('#segmentDuration').value=s?.duration||20;$('#storyDirection').value=s?.story_direction||'';$('#segmentPrompt').value=s?.prompt||'';$('#endingPrompt').value=s?.ending_prompt||'';$('#aiStoryboardHint').textContent='AI会结合标题、所选时长、项目设定和接续来源生成内容，不会自动保存。';$('#refineEnabled').checked=!!s?.refine_enabled;$('#refineDenoise').value=s?.refine_denoise??0.25;$('#refineSteps').value=s?.refine_steps??10;toggleRefineOptions();const candidates=state.project.segments.filter(item=>item.id!==s?.id);$('#sourceSegment').innerHTML=candidates.map(item=>`<option value="${item.id}">片段 ${item.display_order} · ${esc(item.title)}</option>`).join('');const mode=isFirst||!candidates.length?'cut':s?.continuity_mode||'continue';$(`input[name="continuity"][value="${mode}"]`).checked=true;$$('input[name="continuity"]').forEach(x=>x.disabled=isFirst||!candidates.length);if(candidates.length)$('#sourceSegment').value=s?.continuity_source_id||candidates[candidates.length-1].id;toggleSourceOptions();$('#segmentDialogTitle').textContent=s?'编辑故事片段':'添加故事片段';$('#segmentDialog').showModal()}
async function generateStoryboard(){const title=$('#segmentTitle').value.trim(),mode=$('input[name="continuity"]:checked').value,button=$('#generateStoryboardBtn');if(!title)return toast('请先填写片段标题',true);const body={title,duration:+$('#segmentDuration').value,continuity_mode:mode,continuity_source_id:mode==='continue'?+$('#sourceSegment').value:null,story_direction:$('#storyDirection').value.trim(),current_prompt:$('#segmentPrompt').value.trim()};button.disabled=true;button.textContent='AI 正在构思…';$('#aiStoryboardHint').textContent='正在结合项目设定与接续片段生成完整分镜，请稍候。';try{const result=await api(`/api/projects/${state.project.id}/storyboard/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#segmentPrompt').value=result.storyboard;$('#aiStoryboardHint').textContent=`已由 ${result.model_name} 生成，请检查并修改后保存片段。`;toast('AI分镜已生成，请确认后保存')}catch(e){$('#aiStoryboardHint').textContent='生成失败，已保留原有内容。';toast(e.message,true)}finally{button.disabled=false;button.textContent='生成 / 完善分镜'}}
async function saveSegment(e){e.preventDefault();const id=$('#editingSegmentId').value,mode=$('input[name="continuity"]:checked').value,existing=id&&state.project.segments.find(s=>s.id===+id),body={title:$('#segmentTitle').value.trim(),duration:+$('#segmentDuration').value,continuity_mode:mode,continuity_source_id:mode==='continue'?+$('#sourceSegment').value:null,chain_order:existing?.chain_order||state.project.segments.length+1,story_direction:$('#storyDirection').value.trim(),prompt:$('#segmentPrompt').value.trim(),ending_prompt:$('#endingPrompt').value.trim(),refine_enabled:$('#refineEnabled').checked,refine_denoise:+$('#refineDenoise').value,refine_steps:+$('#refineSteps').value};if(!body.title||!body.prompt)return toast('请填写标题和最终本段剧情',true);try{await api(id?`/api/segments/${id}`:`/api/projects/${state.project.id}/segments`,{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#segmentDialog').close();await selectProject(state.project.id);toast(id?'片段已更新':'片段已添加')}catch(e){toast(e.message,true)}}
async function generate(s){if(!state.project.references.length)return toast('请先上传至少一张人物参考图',true);if(s.continuity_mode==='continue'&&s.continuity_source_id){const source=state.project.segments.find(item=>item.id===s.continuity_source_id),sourceActive=['queued','running'].includes(source?.latest_job?.status);if(!source?.videos.length&&!sourceActive)return toast(`请先生成来源片段 ${source?.display_order||''}，或先将它加入生成队列`,true)}try{const tasks=await refreshTasks();if(!tasks||tasks.state==='offline')return toast('ComfyUI 生成引擎当前离线，无法提交任务',true);if(tasks.busy){const ahead=tasks.web.running+tasks.web.queued;const external=tasks.comfyui.running+tasks.comfyui.pending;const detail=external>ahead?`\nComfyUI 另有 ${external} 个任务正在运行或等待。`:'';if(!confirm(`服务器当前繁忙，Web队列已有 ${ahead} 个任务。\n新任务预计排在第 ${ahead+1} 位。${detail}\n\n仍要加入队列吗？`))return}const j=await api(`/api/segments/${s.id}/generate`,{method:'POST'});toast(j.queue_position>1?`已加入队列，当前第 ${j.queue_position} 位`:'任务已开始调度');await refreshTasks();await selectProject(state.project.id);pollJob(j.job_id)}catch(e){toast(e.message,true)}}
function renderCombinedVideos(){const box=$('#combinedVideos'),videos=state.project?.combined_videos||[],ordered=[...(state.project?.segments||[])].sort((a,b)=>(a.chain_order||a.position+1)-(b.chain_order||b.position+1));if(!videos.length){box.innerHTML='';return}box.innerHTML=`<div class="combined-head"><div><span class="eyebrow">FINAL CUTS</span><h3>项目完整成片</h3></div><small>当前串联顺序：${ordered.map(s=>`${s.chain_order||s.position+1}. ${esc(s.title)}`).join(' → ')}</small></div><div class="combined-list">${videos.map((v,index)=>`<article class="combined-item"><div class="video-tags">${index===0?'<span class="video-tag latest">最新合并</span>':''}<span class="video-tag">${formatVideoTime(v.duration_seconds)}</span><span class="video-tag">${v.width}×${v.height}</span><span class="video-tag">${v.source_video_ids.length} 个片段</span></div><video controls preload="metadata" src="/api/combined-videos/${v.id}/stream?v=${encodeURIComponent(v.id)}"></video><div class="video-foot"><span>${formatSize(v.size_bytes)} · ${taskTime(v.created_at)}</span><div><a href="/api/combined-videos/${v.id}/stream?download=true&v=${encodeURIComponent(v.id)}">下载</a><button data-combined-delete="${v.id}">删除</button></div></div></article>`).join('')}</div>`;box.querySelectorAll('[data-combined-delete]').forEach(button=>button.onclick=()=>deleteCombinedVideo(button.dataset.combinedDelete))}
async function generateChain(){if(!state.project?.segments.length)return toast('项目中没有片段',true);const ordered=[...state.project.segments].sort((a,b)=>(a.chain_order||a.position+1)-(b.chain_order||b.position+1));if(!confirm(`将使用每个片段的最新成片，按以下顺序通过 FFmpeg 快速合并：\n${ordered.map(s=>`${s.chain_order||s.position+1}. 片段${s.position+1} ${s.title}`).join('\n')}\n\n不会重新采样或调用 ComfyUI。继续吗？`))return;const button=$('#generateChainBtn');button.disabled=true;button.textContent='正在合并…';try{const result=await api(`/api/projects/${state.project.id}/generate-chain`,{method:'POST'});await selectProject(state.project.id);toast(`已合并 ${result.source_video_ids.length} 个片段`)}catch(e){toast(e.message,true)}finally{button.disabled=false;button.textContent='▶ 合并已有片段'}}
async function deleteCombinedVideo(id){if(!confirm('永久删除这个合并视频？片段原视频不会受影响。'))return;try{await api(`/api/combined-videos/${id}`,{method:'DELETE'});await selectProject(state.project.id);toast('合并视频已物理删除')}catch(e){toast(e.message,true)}}
function enhanceRunningCancelButtons(){for(const segment of state.project?.segments||[]){if(segment.latest_job?.status!=='running')continue;const card=$(`.segment-card[data-id="${segment.id}"]`),generateButton=card?.querySelector('[data-a="generate"]');if(!generateButton||card.querySelector('[data-a="cancel-job"]'))continue;generateButton.insertAdjacentHTML('afterend','<button class="cancel-job" data-a="cancel-job">取消视频生成</button>');card.querySelector('[data-a="cancel-job"]').onclick=()=>cancelJob(segment.latest_job.id)}}
async function cancelJob(id){const job=state.project?.segments.map(segment=>segment.latest_job).find(item=>item?.id===id),running=job?.status==='running';if(!confirm(running?'确认中断当前这次视频生成？\n\n已消耗的生成进度无法恢复，之前成功生成的视频不会被删除。':'确认取消这个排队任务？'))return;const card=job&&$(`.segment-card[data-id="${job.segment_id}"]`),button=card?.querySelector('[data-a="cancel-job"]');if(button){button.disabled=true;button.textContent=running?'正在中断…':'正在取消…'}try{await api(`/api/jobs/${id}/cancel`,{method:'POST'});if(job)updateJobCard({...job,status:'cancelled',phase:'已取消视频生成'});const timer=state.pollers.get(id);if(timer)clearInterval(timer);state.pollers.delete(id);await refreshTasks();if(state.project)await selectProject(state.project.id);toast(running?'视频生成已中断':'排队任务已取消')}catch(e){if(button){button.disabled=false;button.textContent=running?'取消视频生成':'取消排队'}await refreshTasks();if(state.project)await selectProject(state.project.id);toast(e.message,true)}}
function updateJobCard(j){const card=$(`.segment-card[data-id="${j.segment_id}"]`);if(!card)return;const panel=card.querySelector('.job-progress'),active=['queued','running'].includes(j.status),pct=Math.round((j.progress||0)*100);if(panel){panel.classList.toggle('hidden',!active);const phase=panel.querySelector('.progress-head span'),value=panel.querySelector('.progress-head b'),fill=panel.querySelector('.progress-fill'),error=panel.querySelector('.job-error');if(phase)phase.textContent=j.phase||'';if(value)value.textContent=`${pct}%`;if(fill)fill.style.width=`${pct}%`;if(error)error.textContent=j.error||''}const button=card.querySelector('[data-a="generate"]');if(button){button.disabled=active;button.textContent=j.status==='queued'?'排队中':j.status==='running'?'生成中':'生成片段'}const cancel=card.querySelector('[data-a="cancel-job"]');if(cancel){cancel.classList.toggle('hidden',!active);cancel.disabled=false;cancel.textContent=j.status==='running'?'取消视频生成':'取消排队'}}
function pollJob(id){if(state.pollers.has(id))return;const timer=setInterval(async()=>{try{const j=await api(`/api/jobs/${id}`);updateJobCard(j);await refreshTasks();if(['complete','failed','cancelled'].includes(j.status)){clearInterval(timer);state.pollers.delete(id);const projectId=state.project?.id;if(projectId)await selectProject(projectId);toast(j.status==='complete'?'视频生成完成':j.status==='cancelled'?'视频生成已取消':`生成失败：${j.error}`,j.status==='failed')}}catch{}},1800);state.pollers.set(id,timer)}
function requestDeleteSegment(s){state.deleteSegment=s;$('#deleteSegmentName').textContent=s.title;$('#deleteSegmentInput').value='';$('#confirmDeleteSegment').disabled=true;$('#deleteSegmentDialog').showModal();setTimeout(()=>$('#deleteSegmentInput').focus(),50)}
async function confirmDeleteSegment(){const s=state.deleteSegment;if(!s||$('#deleteSegmentInput').value!=='DELETE')return;$('#confirmDeleteSegment').disabled=true;try{await api(`/api/segments/${s.id}`,{method:'DELETE'});$('#deleteSegmentDialog').close();state.deleteSegment=null;await selectProject(state.project.id);toast('片段已删除')}catch(e){$('#confirmDeleteSegment').disabled=false;toast(e.message,true)}}
function requestDeleteVideo(id){state.deleteVideoId=id;$('#deleteVideoInput').value='';$('#confirmDeleteVideo').disabled=true;$('#deleteVideoDialog').showModal();setTimeout(()=>$('#deleteVideoInput').focus(),50)}
async function confirmDeleteVideo(){if(!state.deleteVideoId||$('#deleteVideoInput').value!=='DELETE')return;$('#confirmDeleteVideo').disabled=true;try{await api(`/api/videos/${state.deleteVideoId}`,{method:'DELETE'});$('#deleteVideoDialog').close();state.deleteVideoId=null;await selectProject(state.project.id);toast('视频和关键帧已删除')}catch(e){$('#confirmDeleteVideo').disabled=false;toast(e.message,true)}}
async function uploadPhoto(slot,file){const form=new FormData();form.append('file',file);try{await api(`/api/projects/${state.project.id}/references/${slot}`,{method:'POST',body:form});await selectProject(state.project.id);toast(`人物参考图 ${slot} 已上传`)}catch(e){toast(e.message,true)}}
async function removePhoto(slot){if(!confirm('删除这张人物参考图？'))return;await api(`/api/projects/${state.project.id}/references/${slot}`,{method:'DELETE'});await selectProject(state.project.id)}
function openProjectDialog(){$('#newProjectName').value='';$('#projectDialog').showModal();setTimeout(()=>$('#newProjectName').focus(),50)}
async function createProject(e){e.preventDefault();const name=$('#newProjectName').value.trim();if(!name)return;try{const p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});$('#projectDialog').close();await loadProjects(p.id);toast('项目已创建')}catch(e){toast(e.message,true)}}
async function deleteProject(){if(!confirm(`永久删除项目“${state.project.name}”、人物图和所有视频？`))return;try{await api(`/api/projects/${state.project.id}`,{method:'DELETE'});state.project=null;await loadProjects();toast('项目已删除')}catch(e){toast(e.message,true)}}
async function openLlmConfig(){const dialog=$('#llmConfigDialog');$('#llmConfigPassword').value='';$('#llmApiKey').value='';dialog.showModal();try{const config=await api('/api/settings/llm');$('#llmBaseUrl').value=config.base_url;$('#llmModelName').value=config.model_name;$('#llmApiKeyHint').textContent=config.configured?`当前密钥：${config.api_key_masked}，留空保持不变`:'当前未配置';$('#llmConfigState').textContent=config.configured?'已配置':'未配置';$('#llmConfigUpdated').textContent=config.updated_at?`最后更新：${taskTime(config.updated_at)}`:'保存前不会连接模型服务';$('#llmConfigDot').classList.toggle('ready',config.configured)}catch(e){toast(e.message,true)}}
async function saveLlmConfig(e){e.preventDefault();const button=$('#saveLlmConfig');button.disabled=true;try{await api('/api/settings/llm',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({base_url:$('#llmBaseUrl').value.trim(),api_key:$('#llmApiKey').value.trim(),model_name:$('#llmModelName').value.trim(),password:$('#llmConfigPassword').value})});$('#llmConfigDialog').close();toast('大模型配置已保存')}catch(e){toast(e.message,true)}finally{button.disabled=false}}
$('#sceneConfig').ontoggle=()=>{if(state.project)state.sceneConfigOpen.set(state.project.id,$('#sceneConfig').open)};$('#exportProjectBtn').onclick=exportProject;$('#exportStoryboardBtn').onclick=exportStoryboard;$('#llmConfigBtn').onclick=openLlmConfig;$('#llmConfigForm').onsubmit=saveLlmConfig;$('#closeLlmConfig').onclick=$('#cancelLlmConfig').onclick=()=>$('#llmConfigDialog').close();
$('#newProjectBtn').onclick=openProjectDialog;$('#emptyCreateBtn').onclick=openProjectDialog;$('#confirmProjectBtn').onclick=createProject;$('#saveProjectBtn').onclick=()=>saveProject().catch(e=>toast(e.message,true));$('#deleteProjectBtn').onclick=deleteProject;$('#addSegmentBtn').onclick=()=>openSegment();$('#generateChainBtn').onclick=generateChain;$('#saveSegmentBtn').onclick=saveSegment;$('#refineEnabled').onchange=toggleRefineOptions;$$('input[name="continuity"]').forEach(input=>input.onchange=toggleSourceOptions);$('#taskCenterBtn').onclick=async()=>{await refreshTasks();$('#taskDialog').showModal()};$('#closeTaskCenter').onclick=()=>$('#taskDialog').close();$('#deleteSegmentInput').oninput=e=>{$('#confirmDeleteSegment').disabled=e.target.value!=='DELETE'};$('#deleteSegmentInput').onkeydown=e=>{if(e.key==='Enter'&&e.target.value==='DELETE'){e.preventDefault();confirmDeleteSegment()}};$('#confirmDeleteSegment').onclick=confirmDeleteSegment;$('#cancelDeleteSegment').onclick=()=>{$('#deleteSegmentDialog').close();state.deleteSegment=null};$('#deleteVideoInput').oninput=e=>{$('#confirmDeleteVideo').disabled=e.target.value!=='DELETE'};$('#deleteVideoInput').onkeydown=e=>{if(e.key==='Enter'&&e.target.value==='DELETE'){e.preventDefault();confirmDeleteVideo()}};$('#confirmDeleteVideo').onclick=confirmDeleteVideo;$('#cancelDeleteVideo').onclick=()=>{$('#deleteVideoDialog').close();state.deleteVideoId=null};$$('.dialog-cancel').forEach(button=>button.onclick=()=>button.closest('dialog').close());$$('.photo-slot').forEach(box=>{const slot=+box.dataset.slot,input=box.querySelector('input');box.onclick=e=>{if(!e.target.closest('.photo-remove'))input.click()};input.onchange=()=>input.files[0]&&uploadPhoto(slot,input.files[0]);box.querySelector('.photo-remove').onclick=e=>{e.stopPropagation();removePhoto(slot)}});window.addEventListener('resize',drawRelations);
generateChain=async function(){if(!state.project?.segments.length)return toast('项目中没有片段',true);const ordered=[...state.project.segments].sort((a,b)=>(a.chain_order||a.position+1)-(b.chain_order||b.position+1));if(!confirm(`将使用每个片段已选择的视频版本，按以下顺序通过 FFmpeg 快速合并：\n${ordered.map(s=>{const video=s.videos.find(v=>v.selected_for_merge);return `${s.chain_order||s.position+1}. 片段${s.position+1} ${s.title}${video?`（视频 ${video.id}）`:'（未选择视频）'}`}).join('\n')}\n\n不会重新采样或调用 ComfyUI。继续吗？`))return;const button=$('#generateChainBtn');button.disabled=true;button.textContent='正在合并…';try{const result=await api(`/api/projects/${state.project.id}/generate-chain`,{method:'POST'});await selectProject(state.project.id);toast(`已合并 ${result.source_video_ids.length} 个片段`)}catch(e){toast(e.message,true)}finally{button.disabled=false;button.textContent='▶ 合并已有片段'}};
const generateIncludedChain=async function(){const included=(state.project?.segments||[]).filter(segment=>segment.include_in_merge).sort((a,b)=>(a.chain_order||a.position+1)-(b.chain_order||b.position+1));if(!included.length)return toast('请至少勾选一个参与合并的片段',true);if(!confirm(`将合并以下已勾选片段：\n${included.map(s=>{const video=s.videos.find(v=>v.selected_for_merge);return `${s.chain_order||s.position+1}. 片段${s.position+1} ${s.title}${video?`（视频 ${video.id}）`:'（未选择视频）'}`}).join('\n')}\n\n未勾选片段将被跳过，不会重新采样或调用 ComfyUI。继续吗？`))return;const button=$('#generateChainBtn');button.disabled=true;button.textContent='正在合并…';try{const result=await api(`/api/projects/${state.project.id}/generate-chain`,{method:'POST'});await selectProject(state.project.id);toast(`已合并 ${result.source_video_ids.length} 个片段`)}catch(e){toast(e.message,true)}finally{button.disabled=false;button.textContent='▶ 合并已有片段'}};
$('#generateChainBtn').onclick=generateIncludedChain;
const generateStoryboardBase=generateStoryboard;
generateStoryboard=async function(){const title=$('#segmentTitle').value.trim(),mode=$('input[name="continuity"]:checked').value,button=$('#generateStoryboardBtn');if(!title)return toast('请先填写片段标题',true);const body={title,duration:+$('#segmentDuration').value,continuity_mode:mode,continuity_source_id:mode==='continue'?+$('#sourceSegment').value:null,story_direction:$('#storyDirection').value.trim(),world_prompt:$('#segmentWorldPrompt').value.trim(),current_prompt:$('#segmentPrompt').value.trim()};button.disabled=true;button.textContent='AI 正在构思…';$('#aiStoryboardHint').textContent='正在结合项目设定与接续片段生成完整分镜，请稍候。';try{const result=await api(`/api/projects/${state.project.id}/storyboard/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#segmentPrompt').value=result.storyboard;$('#aiStoryboardHint').textContent=`已由 ${result.model_name} 生成，请检查并修改后保存片段。`;toast('AI分镜已生成，请确认后保存')}catch(e){$('#aiStoryboardHint').textContent='生成失败，已保留原有内容。';toast(e.message,true)}finally{button.disabled=false;button.textContent='生成 / 完善分镜'}};
$('#generateStoryboardBtn').onclick=generateStoryboard;
$('#loginForm').onsubmit=login;$('#logoutBtn').onclick=logout;$('#userAdminBtn').onclick=openUserAdmin;$('#closeUserAdmin').onclick=()=>$('#userAdminDialog').close();$('#userCreateForm').onsubmit=createUser;
const openSegmentBase=openSegment;
openSegment=function(s=null){openSegmentBase(s);state.pendingSegmentImages.clear();$('#segmentWorldPrompt').value=s?.world_prompt||'';fillSegmentImages(s)};
function fillSegmentImages(s){for(const slot of [1,2,3,4,5]){const box=$(`.segment-photo-slot[data-slot="${slot}"]`),ref=s?.references?.find(item=>item.slot===slot);box.classList.toggle('has-image',!!ref);box.querySelector('img').src=ref?`/api/segments/${s.id}/references/${slot}?t=${Date.now()}`:'';box.querySelector('input').value=''}}
async function uploadSegmentImage(slot,file,segmentId){const form=new FormData();form.append('file',file);await api(`/api/segments/${segmentId}/references/${slot}`,{method:'POST',body:form})}
async function chooseSegmentImage(slot,file){const id=+$('#editingSegmentId').value,box=$(`.segment-photo-slot[data-slot="${slot}"]`);box.querySelector('img').src=URL.createObjectURL(file);box.classList.add('has-image');if(id){try{await uploadSegmentImage(slot,file,id);toast(`片段图片${slot}已上传`)}catch(e){toast(e.message,true)}}else state.pendingSegmentImages.set(slot,file)}
async function removeSegmentImage(slot){const id=+$('#editingSegmentId').value,box=$(`.segment-photo-slot[data-slot="${slot}"]`);if(id){if(!confirm(`删除片段图片${slot}？`))return;await api(`/api/segments/${id}/references/${slot}`,{method:'DELETE'})}else state.pendingSegmentImages.delete(slot);box.classList.remove('has-image');box.querySelector('img').src=''}
saveSegment=async function(e){e.preventDefault();const id=$('#editingSegmentId').value,mode=$('input[name="continuity"]:checked').value,existing=id&&state.project.segments.find(s=>s.id===+id),body={title:$('#segmentTitle').value.trim(),duration:+$('#segmentDuration').value,continuity_mode:mode,continuity_source_id:mode==='continue'?+$('#sourceSegment').value:null,chain_order:existing?.chain_order||state.project.segments.length+1,story_direction:$('#storyDirection').value.trim(),world_prompt:$('#segmentWorldPrompt').value.trim(),prompt:$('#segmentPrompt').value.trim(),ending_prompt:$('#endingPrompt').value.trim(),refine_enabled:$('#refineEnabled').checked,refine_denoise:+$('#refineDenoise').value,refine_steps:+$('#refineSteps').value};if(!body.title||!body.prompt)return toast('请填写标题和最终本段剧情',true);try{const saved=await api(id?`/api/segments/${id}`:`/api/projects/${state.project.id}/segments`,{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});for(const [slot,file] of state.pendingSegmentImages)await uploadSegmentImage(slot,file,saved.id);state.pendingSegmentImages.clear();$('#segmentDialog').close();await selectProject(state.project.id);toast(id?'片段已更新':'片段已添加')}catch(e){toast(e.message,true)}};
const generateOriginal=generate;
generate=async function(s){if(!state.project.references.length&&!s.references?.length)return toast('请先上传至少一张全局人物图或片段约束图',true);if(s.continuity_mode==='continue'&&s.continuity_source_id){const source=state.project.segments.find(item=>item.id===s.continuity_source_id),sourceActive=['queued','running'].includes(source?.latest_job?.status);if(!source?.videos.length&&!sourceActive)return toast(`请先生成来源片段 ${source?.display_order||''}，或先将它加入生成队列`,true)}try{const tasks=await refreshTasks();if(!tasks||tasks.state==='offline')return toast('GPU 当前离线，无法提交任务',true);if(tasks.busy){const ahead=tasks.web.running+tasks.web.queued,external=tasks.comfyui.running+tasks.comfyui.pending,detail=external?`\n另有 ${external} 个 ComfyUI 外部任务正在运行或等待。`:'';if(!confirm(`GPU 当前繁忙，全局Web队列已有 ${ahead} 个任务。\n新任务预计排在第 ${ahead+1} 位。${detail}\n\n仍要加入队列吗？`))return}const job=await api(`/api/segments/${s.id}/generate`,{method:'POST'});toast(job.queue_position>1?`已加入队列，当前第 ${job.queue_position} 位`:'任务已开始调度');await refreshTasks();await selectProject(state.project.id);pollJob(job.job_id)}catch(e){toast(e.message,true)}};
const generateBase=generate;
generate=function(s){if(!state.project.references.length&&!s.references?.length)return toast('请先上传至少一张全局人物图或片段约束图',true);if(state.project.references.length)return generateBase(s);state.project.references.push({});const result=generateBase(s);state.project.references.pop();return result};
$('#saveSegmentBtn').onclick=saveSegment;
$$('.segment-photo-slot').forEach(box=>{const slot=+box.dataset.slot,input=box.querySelector('input');box.onclick=event=>{if(!event.target.closest('.segment-photo-remove'))input.click()};input.onchange=()=>input.files[0]&&chooseSegmentImage(slot,input.files[0]);box.querySelector('.segment-photo-remove').onclick=event=>{event.stopPropagation();removeSegmentImage(slot).catch(error=>toast(error.message,true))}});
function enableEpisodeDrag(){const grid=$('.episode-grid');if(!grid)return;let dragged=null,moved=false;for(const card of grid.querySelectorAll('.episode-card')){card.draggable=true;card.title='拖动调整片段顺序';card.addEventListener('dragstart',event=>{if(event.target.closest('.episode-edit')){event.preventDefault();return}dragged=card;moved=false;card.classList.add('dragging');grid.classList.add('sorting');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',card.dataset.episodeId)});card.addEventListener('dragover',event=>{if(!dragged||dragged===card)return;event.preventDefault();const rect=card.getBoundingClientRect(),before=event.clientY<rect.top+rect.height/2&&(Math.abs(event.clientY-(rect.top+rect.height/2))>Math.abs(event.clientX-(rect.left+rect.width/2))||event.clientX<rect.left+rect.width/2);grid.insertBefore(dragged,before?card:card.nextSibling);moved=true});card.addEventListener('dragend',()=>{card.classList.remove('dragging');grid.classList.remove('sorting');if(moved)saveDraggedEpisodeOrder(grid);dragged=null})}}
function enhanceMergeInclusion(){for(const segment of state.project?.segments||[]){const card=$(`.episode-card[data-episode-id="${segment.id}"]`);if(!card)continue;const label=document.createElement('label');label.className='merge-inclusion';label.title='勾选后作为有效片段参与合并';label.innerHTML=`<input type="checkbox" ${segment.include_in_merge?'checked':''}><span>有效片段</span>`;card.appendChild(label);label.onclick=event=>event.stopPropagation();const input=label.querySelector('input');input.onchange=()=>setMergeInclusion(segment,input)}}
async function setMergeInclusion(segment,input){input.disabled=true;try{await api(`/api/segments/${segment.id}/merge-inclusion`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({include_in_merge:input.checked})});segment.include_in_merge=input.checked;input.closest('.episode-card').classList.toggle('merge-excluded',!input.checked);toast(input.checked?`片段${segment.display_order}将参与合并`:`片段${segment.display_order}已排除合并`)}catch(e){input.checked=!!segment.include_in_merge;toast(e.message,true)}finally{input.disabled=false}}
async function saveDraggedEpisodeOrder(grid){const ids=[...grid.querySelectorAll('.episode-card')].map(card=>+card.dataset.episodeId),original=state.project.segments.map(segment=>segment.id);if(ids.every((id,index)=>id===original[index]))return;grid.classList.add('saving-order');try{await api(`/api/projects/${state.project.id}/chain-order`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({segment_ids:ids})});await selectProject(state.project.id);toast('片段顺序已保存')}catch(e){await selectProject(state.project.id);toast(e.message,true)}}
const renderEpisodeShelfDragBase=renderEpisodeShelf;
renderEpisodeShelf=function(){renderEpisodeShelfDragBase();enableEpisodeDrag();enhanceMergeInclusion();for(const segment of state.project?.segments||[])$(`.episode-card[data-episode-id="${segment.id}"]`)?.classList.toggle('merge-excluded',!segment.include_in_merge)};
